"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[9551],{81128:function(a){a.exports=JSON.parse('{"page_title":"Ramadan 2026 | Complete Guide & Resources","meta_description":"Complete guide for Ramadan 1447 AH (2026 CE): key dates, how to fast, prayers made easy, Quran plans, charity guidance, health tips, duas, tools, and verified resources.","last_updated":"2025-03-01","data_sources":[{"label":"Quran.com","link":"https://quran.com"},{"label":"Sunnah.com","link":"https://sunnah.com"},{"label":"IslamQA.info","link":"https://islamqa.info"},{"label":"Yaqeen Institute","link":"https://yaqeeninstitute.org"},{"label":"SeekersGuidance","link":"https://seekersguidance.org"}],"labels":{"references":"References","open_video":"Open video","open_tool":"Launch tool","open_tool_title":"Launch tool","open_tool_aria":"Launch tool in a new tab","download":"Download","watch_short":"Watch short","highlights":"Highlights","view_source":"View","duration_prefix":"Duration","resource_label":"Resource"},"header":{"title":"Ramadan 2026 (1447 AH)","subtitle":"The Month of Quran, Fasting, and Spiritual Renewal","banner_image":"/images/ramadan-hero-pexels.jpg","alt_text":"Grand mosque exterior under a twilight sky","stats":{"last_updated_label":"Last updated","data_sources_label":"Data sources"}},"nav_links":[{"label":"What is Ramadan","href":"#overview"},{"label":"History","href":"#history"},{"label":"Key dates","href":"#key-dates"},{"label":"How to fast","href":"#how-to-fast"},{"label":"FAQ","href":"#faq"},{"label":"Recources","href":"#platforms"},{"label":"Quran plans","href":"#quran-plans"},{"label":"Personal plans","href":"#personal-plans"},{"label":"Tools","href":"#tools"},{"label":"Charity","href":"#charity"},{"label":"Health tips","href":"#health"},{"label":"Short clips","href":"#shorts"}],"overview":{"section_title":"What Is Ramadan?","subtitle":"Ramadan is the ninth month of the Islamic lunar calendar. It is a month of fasting from dawn to sunset, focused worship, Quran recitation, community care, and spiritual renewal.","body":["The Quran describes Ramadan as the month in which the Quran was revealed as guidance for humanity. Muslims fast to develop taqwa (God-consciousness), discipline their desires, and increase empathy for those in need.","Beyond fasting, Ramadan is a time to elevate worship through prayer, charity, and reflection. Families gather, communities host iftars, and masajid become centers of learning and service.","Every day in Ramadan is an invitation to reset habits, strengthen spiritual focus, and renew intentions with sincerity."],"key_points_title":"Key ideas to remember","key_points":["Fasting is an act of worship and self-discipline.","Ramadan is the month in which the Quran was revealed.","The last ten nights are especially blessed, including Laylat al-Qadr.","Charity and community care are central to the month.","Every day is an opportunity to improve character and habits."],"references":[{"source":"Qur\'an","citation":"Al-Baqarah 2:183-185","source_site":"quran.com","embedded_text":"Allah prescribed fasting for believers so they may attain taqwa, and identified Ramadan as the month in which the Quran was revealed as guidance."},{"source":"Qur\'an","citation":"Al-Qadr 97:1-5","source_site":"quran.com","embedded_text":"Laylat al-Qadr is described as better than a thousand months and a night filled with peace by Allah\'s permission."},{"source":"Hadith","citation":"Sahih al-Bukhari 38; Sahih Muslim 760","source_site":"sunnah.com","embedded_text":"The Prophet taught that whoever fasts Ramadan with faith and hope of reward will have previous sins forgiven."}]},"history":{"section_title":"History & Significance","subtitle":"Ramadan is linked to the Quranic revelation and the obligation of fasting. Its devotional rhythm has shaped Muslim worship, ethics, and communal life for centuries.","body":["The Quran frames fasting in Ramadan as a prescribed act for believers and ties the month to revelation and guidance.","Prophetic practice established suhoor, iftar at sunset, and intensified night worship, while the last ten nights emphasize Laylat al-Qadr and spiritual retreat (i\'tikaf).","Across centuries, Ramadan shaped daily routines, public worship, and charitable life, anchored by mosques, learning circles, and family gatherings.","Modern Ramadan carries these traditions worldwide through organized charity, community programming, and digital learning."],"timeline":[{"number":1,"period":"c. 610 CE (13 BH)","detail":"The first revelation is tied to Ramadan, and the Quran identifies this month as the period of guidance for humanity.","reference":"Qur\'an 96:1-5; Qur\'an 97:1-5; Qur\'an 2:185","reference_site":"quran.com"},{"number":2,"period":"624 CE (2 AH)","detail":"The command to fast in Ramadan is formally legislated, with clear rulings on the goal, timeframe, and concessions.","reference":"Qur\'an 2:183-187","reference_site":"quran.com"},{"number":3,"period":"632-661 CE (Rashidun Caliphate)","detail":"Companions preserved Quran transmission and organized Ramadan night prayer at scale for community worship.","reference":"Sahih al-Bukhari 4986; Sahih al-Bukhari 2010","reference_site":"sunnah.com"},{"number":4,"period":"Classical Sunni Practice","detail":"Iftar at sunset, suhoor before dawn, and intensified qiyam became stable features of Ramadan worship across regions.","reference":"Sahih al-Bukhari 1957; Sahih Muslim 1095","reference_site":"sunnah.com"},{"number":5,"period":"Contemporary Fiqh Clarification","detail":"Modern fatwa platforms continue to explain exemptions, makeup fasts, fidyah, and valid reasons for breaking the fast.","reference":"IslamQA Ramadan topic hub and fasting rulings","reference_site":"IslamQA.info"},{"number":6,"period":"Community Teaching in the Digital Era","detail":"Structured online courses and answer services broaden access to Ramadan fiqh, adab, and worship preparation.","reference":"SeekersGuidance Ramadan answers and curriculum pages","reference_site":"SeekersGuidance"},{"number":7,"period":"Global Reflection Projects","detail":"Research-driven Ramadan series and reflection journals increase access to spiritually grounded educational content.","reference":"Yaqeen Institute Ramadan collection","reference_site":"Yaqeen Institute"},{"number":8,"period":"Contemporary Observance (21st Century)","detail":"Ramadan is globally shared but locally timed, with communities combining moon-sighting announcements, digital planning, and local service.","reference":"Qur\'an 2:185 with applied guidance from Sunni fiqh references","reference_site":"quran.com / Sunnah.com / IslamQA.info / SeekersGuidance / Yaqeen Institute"}],"notable_figures":{"title":"Scholars & Voices","items":[{"name":"Ibn Abbas (d. 687 CE)","note":"Early Qur\'anic exegete whose explanations shaped how Muslims understand verses about fasting."},{"name":"Imam Malik (d. 795 CE)","note":"Documented Madinan practice, including Ramadan customs and community observance."},{"name":"Imam al-Shafi\'i (d. 820 CE)","note":"Systematized legal principles that influenced fasting rulings across regions."},{"name":"Imam al-Nawawi (d. 1277 CE)","note":"Compiled hadith and devotional guidance that shaped Ramadan practice."}]},"regional_practices":{"title":"Regional Traditions","items":[{"region":"Egypt (Cairo)","detail":"Lantern processions and communal iftars became distinctive Ramadan features."},{"region":"Ottoman cities (Istanbul)","detail":"Public iftar tents and endowments supported travelers and the poor."},{"region":"West Africa (Sahel)","detail":"Quran recitation circles and night study gatherings remain a hallmark."},{"region":"South & Southeast Asia","detail":"Large taraweeh congregations and neighborhood iftars reinforce community bonds."},{"region":"Diaspora communities","detail":"Mosques and Islamic centers host open iftars and service drives to build cohesion."}]},"references":[{"source":"Qur\'an","citation":"Al-Baqarah 2:183-187","source_site":"quran.com","embedded_text":"These verses establish fasting in Ramadan, name the month of revelation, and provide core legal concessions for illness and travel."},{"source":"Qur\'an","citation":"Al-Baqarah 2:185","source_site":"quran.com","embedded_text":"Ramadan is defined as the month of Quran revelation and guidance, linking worship routine directly to revelation."},{"source":"Hadith","citation":"Sahih al-Bukhari 2010; Sahih al-Bukhari 4986","source_site":"sunnah.com","embedded_text":"These narrations are used for Ramadan congregational night prayer and the compilation-preservation history of the Qur\'an."},{"source":"Fiqh Guidance","citation":"Ramadan guidance collections","source_site":"IslamQA.info / SeekersGuidance / Yaqeen Institute","embedded_text":"Contemporary scholarship explains how classical rulings are applied in modern schedules, health contexts, and community conditions."}]},"important_dates":{"section_title":"Ramadan 1447 AH (2026 CE) – Umm al-Qura Calendar (Official Saudi Calendar)","subtitle":"These dates represent the Umm al-Qura administrative calendar used by Saudi Arabia for civil and planning purposes. They are the most widely published pre-calculated dates for 1447 AH.","global_note":"IMPORTANT: These dates are based on the Umm al-Qura calendar calculations. While this is the official calendar of Saudi Arabia, the actual beginning and end of Ramadan remain subject to the official moon sighting by the Saudi Supreme Court. Final announcements may differ by ±1 day.","methodology":"Umm al-Qura Calendar (Saudi Arabia). Based on astronomical calculations permitting visibility of the crescent somewhere in the world. Dates verified against the official Riyadh prayer timetable for 1447 AH [citation:3] and royal decree dating (24 Sha\'ban 1447 AH = 12 February 2026) [citation:5][citation:10].","dates":[{"event":"First Taraweeh Night","gregorian_date":"February 18, 2026 (after Maghrib)","hijri_date":"29 Sha\'ban 1447 AH","description":"First Taraweeh prayer is held the night immediately preceding the first day of fasting. Umm al-Qura calendar basis.","type":"start"},{"event":"First Day of Ramadan (Fasting Begins)","gregorian_date":"February 19, 2026","hijri_date":"1 Ramadan 1447 AH","description":"VERIFIED UMM AL-QURA DATE. Confirmed by Riyadh & Makkah 1447 AH prayer timetable [citation:3] and derived from royal decree dating (Sha\'ban 24 = Feb 12).","type":"start"},{"event":"First Friday of Ramadan","gregorian_date":"February 20, 2026","hijri_date":"2 Ramadan 1447 AH","description":"First Jumu\'ah of the month. Hijri date corrected to reflect Feb 19 start date.","type":"special"},{"event":"Mid-Ramadan (15th Night)","gregorian_date":"Night of March 4–5, 2026","hijri_date":"15 Ramadan 1447 AH","description":"Occurs on the evening entering the 15th of Ramadan. Gregorian date: March 4 (evening) / March 5 (day).","type":"special"},{"event":"Last 10 Nights Begin","gregorian_date":"Evening of March 9, 2026","hijri_date":"20 Ramadan 1447 AH","description":"Marked by Maghrib prayer on the 20th of Ramadan. Intensified worship begins.","type":"special"},{"event":"Laylat al-Qadr (Night of Decree)","gregorian_date":"Not fixed, Seek on odd nights: 21, 23, 25, 27, 29","hijri_date":"Last 10 odd nights (21, 23, 25, 27, 29 Ramadan)","description":"The Umm al-Qura calendar does not fix Laylat al-Qadr to a specific Gregorian date. The 27th night corresponds to the evening of **March 16, 2026**, entering the day of March 17, 2026. This is the most anticipated night but not definitive.","type":"special"},{"event":"Zakat al-Fitr Deadline","gregorian_date":"Before Eid prayer (March 21, 2026)","hijri_date":"End of Ramadan","description":"Must be paid before Eid prayer. Based on Umm al-Qura Eid date.","type":"special"},{"event":"Eid al-Fitr","gregorian_date":"March 21, 2026","hijri_date":"1 Shawwal 1447 AH","description":"VERIFIED UMM AL-QURA DATE. Ramadan 30 = March 20; therefore 1 Shawwal = March 21. Confirmed by Riyadh prayer timetable (Ramadan ends March 20; Eid is March 21) [citation:3].","type":"eid"}],"verification_footnotes":["✅ 1 Ramadan 1447 AH = February 19, 2026. Source: Almosafer Ramadan 2026 timetable (Riyadh/Makkah), explicitly labeled \'Umm al-Qura calendar\' [citation:3].","✅ 24 Sha\'ban 1447 AH = February 12, 2026. Source: Royal decree for Salat Al-Istisqa [citation:5][citation:10]. Counting forward: Feb 13 (25 Sha\'ban), Feb 14 (26), Feb 15 (27), Feb 16 (28), Feb 17 (29), Feb 18 (30 Sha\'ban*), Feb 19 (1 Ramadan). *Umm al-Qura typically assigns 30 days to Sha\'ban, confirming Feb 19 start.","✅ 1 Shawwal 1447 AH = March 21, 2026. Source: Ramadan 30 = March 20 [citation:3]; therefore Eid = March 21.","⚠️ Minor discrepancy noted: Some news sources incorrectly state the Umm al-Qura calendar predicts Feb 18 [citation:6][citation:9]. The printed prayer timetable for 1447 AH conclusively shows Feb 19. This JSON reflects the official printed calendar."]},"moon_sighting":{"title":"Moon-sighting adjustment instructions","intro":"Ramadan depends on the lunar crescent. These steps help you stay aligned with local moon-sighting announcements while keeping your plan flexible.","steps":["Follow the final announcement from your local masjid, Islamic council, or moon-sighting committee before committing to the start of Ramadan.","Keep both 29- and 30-day plans handy so you can switch the calendar as soon as you hear whether the crescent was seen.","If the crescent is not confirmed on the 29th night, extend the current day of preparation and begin fasting the next evening while still waiting for confirmation.","Note who confirmed the sighting (community leader, scholar, or committee) and which geographic region they represented so your family can confidently follow the approved schedule."],"note":"Right after the official sighting, update the planner start date and adapt reminders, printouts, and digital exports to the confirmed timeline."},"how_to_fast":{"section_title":"How To Fast (Do\'s & Don\'ts)","intro":"Fasting is from dawn to sunset with the intention (niyyah). The goal is worship, discipline, and avoiding what breaks the fast.","cards":[{"title":"Do\'s","items":["Make intention before Fajr.","Eat a balanced Suhoor and hydrate well.","Pray on time and read Quran daily.","Break fast promptly at sunset with dates and water if possible.","Be mindful of behavior, speech, and time.","Make dua before Iftar - it is a special time for acceptance."]},{"title":"Don\'ts","items":["Do not eat or drink between Fajr and Maghrib.","Avoid backbiting, arguments, and harmful speech.","Avoid overeating at Iftar.","Do not neglect prayers or Quran.","Avoid wasting time in unhelpful activities."]},{"title":"Exemptions","items":["Children before puberty","The ill","Travelers","Pregnant or nursing women","Menstruating women"]}],"references":[{"source":"Qur\'an","citation":"Al-Baqarah 2:183-187","source_site":"quran.com","embedded_text":"These verses define the obligation, the fasting window from dawn to night, and legal allowances for hardship."},{"source":"Hadith","citation":"Sahih al-Bukhari 1904; Sahih Muslim 1151","source_site":"sunnah.com","embedded_text":"Prophetic guidance clarifies intention, what invalidates fasting, and the reward connected to sincere fasting."},{"source":"Fiqh Q&A","citation":"Common fasting rulings","source_site":"IslamQA.info / SeekersGuidance","embedded_text":"Scholarly answers explain practical edge cases such as sickness, travel, pregnancy, medication timing, and makeup fasts."}]},"quran_reading_plans":{"section_title":"Quran Reading Plans (3 Levels)","intro":"Choose a plan that fits your schedule and energy. Consistency matters most.","plans":[{"level":"Beginner","daily_target":"4-6 pages","time_needed":"15-25 minutes","structure":"After Fajr + before sleep","goal":"Finish a meaningful portion and build a daily habit.","split":"2 short sessions","tips":["Read after Fajr when focus is strongest.","Listen to audio while commuting or walking.","Track progress on a simple checklist."]},{"level":"Intermediate","daily_target":"1 Juz","time_needed":"45-60 minutes","structure":"Split across 5 prayers","goal":"Complete the Quran once by Eid.","split":"5 short segments","tips":["Read 4-5 pages after each prayer.","Use the evening to catch up if needed.","Pair reading with reflection notes."]},{"level":"Advanced","daily_target":"1.5-2 Juz","time_needed":"90-120 minutes","structure":"Morning + afternoon + night","goal":"Complete the Quran more than once.","split":"3 focused sessions","tips":["Commit to a longer morning session.","Use Taraweeh recitation as part of the goal.","Review a translation alongside recitation."]}],"references":[{"source":"Qur\'an","citation":"Al-Baqarah 2:185","source_site":"quran.com","embedded_text":"Ramadan is explicitly framed around Quran guidance, making daily recitation and study central to the month."},{"source":"Hadith","citation":"Sahih al-Bukhari 1901; Sahih Muslim 760","source_site":"sunnah.com","embedded_text":"Prophetic teachings connect Ramadan fasting and night prayer to purification and spiritual growth."},{"source":"Reflection & Study","citation":"Ramadan reading resources","source_site":"Yaqeen Institute / SeekersGuidance","embedded_text":"Structured learning paths and reflection guides support consistent Quran goals for different schedules."}]},"personal_plans":{"section_title":"Personal Plans (Long-Form)","intro":"Choose a plan that matches your lifestyle and sustain it for 30 days.","daily_flow_title":"Daily flow","weekly_focus_title":"Weekly focus","plans":[{"title":"Quiet Renewal Plan","who_for":"Students and solo worshippers","overview":"A slower, reflective pace focused on Quran, journaling, and community check-ins.","focus":"Spiritual depth and daily consistency.","daily_flow":["Fajr + 10 minutes reflection","Midday: 6 pages Quran","Asr: 5-minute dhikr","After Isha: Taraweeh + short dua"],"weekly_focus":["Week 1: Intention and habit building","Week 2: Deepening Quran connection","Week 3: Night worship focus","Week 4: Gratitude and giving"],"accountability":"Weekly check-in with a friend or mentor."},{"title":"Family Connection Plan","who_for":"Parents and households","overview":"Shared worship with kids, simple lessons, and family goals.","focus":"Family unity and shared learning.","daily_flow":["Suhoor: one short Quran reflection","Maghrib: gratitude circle","After Taraweeh: 15-minute story or Quran"],"weekly_focus":["Week 1: Set family goals","Week 2: Add a family charity project","Week 3: Quran memorization night","Week 4: Eid preparation + reflection"],"accountability":"Family chart tracking prayers and reading."},{"title":"Working Professional Plan","who_for":"Busy schedules","overview":"Short, consistent blocks that fit around work and commuting.","focus":"Micro-habits and consistency.","daily_flow":["Morning commute: Quran audio","Lunch break: 2 pages reading","Evening: 10-minute dhikr + dua","Weekend: longer reflection session"],"weekly_focus":["Week 1: Align calendar","Week 2: Increase charity","Week 3: Add night prayer twice","Week 4: Finish Quran goal"],"accountability":"Set reminders and a weekly target review."},{"title":"Community Service Plan","who_for":"Volunteers and organizers","overview":"Balance worship with consistent service and community care.","focus":"Service and leadership.","daily_flow":["Post-Dhuhr: 20 minutes planning","Evening: serve at iftar or food bank","Night: Taraweeh and dua"],"weekly_focus":["Week 1: Identify a need","Week 2: Build a small volunteer team","Week 3: Host a community iftar","Week 4: Wrap-up and gratitude"],"accountability":"Weekly debrief with the team."},{"title":"Beginner Step-Up Plan","who_for":"New to consistent Ramadan routines","overview":"A gentle ramp-up plan that builds confidence with short, repeatable habits.","focus":"Consistency over intensity.","daily_flow":["Fajr: 5 minutes of Quran + simple dua","Dhuhr: 2 pages of Quran","Maghrib: gratitude note + family check-in","Isha: short Taraweeh or 2 rakaat at home"],"weekly_focus":["Week 1: Set a realistic daily target","Week 2: Add a short reflection journal","Week 3: Increase Quran time by 5 minutes","Week 4: Maintain routine and prepare for Eid"],"accountability":"Track progress daily and celebrate small wins."},{"title":"Night Worship Plan","who_for":"Those focusing on the last 10 nights","overview":"Structured routine to maximize Qiyam, dua, and Quran in the evenings.","focus":"Deep night worship and focused dua.","daily_flow":["After Maghrib: light meal + rest","After Isha: Taraweeh with focus","Late night: 20 minutes Quran + dua","Before Suhoor: 2-4 rakaat Qiyam"],"weekly_focus":["Week 1: Prepare sleep schedule","Week 2: Add a dua list for family","Week 3: Increase Qiyam duration","Week 4: Focus on Laylat al-Qadr"],"accountability":"Set a nightly alarm and keep a short dua checklist."}]},"charity_guide":{"section_title":"Charity Guide (Zakat al-Fitr Made Simple)","intro":"Charity is central in Ramadan. Zakat al-Fitr is obligatory before Eid prayer, while ongoing sadaqah builds compassion.","sadaqah_title":"Sadaqah ideas","giving_checklist_title":"Giving checklist","overview":["Zakat al-Fitr purifies the fasting person from minor shortcomings and ensures everyone can celebrate Eid with dignity.","Sadaqah is voluntary charity given throughout the month. Even small, consistent giving can have a large impact."],"zakat_al_fitr":{"title":"Zakat al-Fitr basics","points":["A required charity per person in the household, given before Eid prayer.","Paid before Eid prayer, preferably during Ramadan.","Every eligible Muslim who can afford it pays for themselves and dependents.","Equivalent to a staple food amount (varies by region).","Give through a local masjid or trusted charity organization."]},"sadaqah_ideas":["Sponsor iftar meals","Support local food banks","Contribute to masjid programs","Help neighbors and community initiatives","Share educational resources","Volunteer time and skills"],"giving_checklist":["Set a realistic daily or weekly amount.","Choose 1-2 trusted organizations.","Include a family charity goal if possible.","Give before Eid for Zakat al-Fitr."],"impact_notes":["Small, consistent charity builds long-term benefit.","Prioritize local needs alongside global relief."],"references":[{"source":"Qur\'an","citation":"Al-Baqarah 2:177","source_site":"quran.com","embedded_text":"Righteousness includes financial giving to relatives, vulnerable people, and those in need."},{"source":"Hadith","citation":"Sahih al-Bukhari 1902; Sahih Muslim 2308","source_site":"sunnah.com","embedded_text":"The Prophet was described as especially generous in Ramadan, encouraging expanded charity during this month."},{"source":"Fiqh Q&A","citation":"Zakat al-Fitr and sadaqah guidance","source_site":"IslamQA.info / SeekersGuidance","embedded_text":"Practical rulings explain who pays Zakat al-Fitr, timing before Eid prayer, and distribution priorities."}]},"health_food_tips":{"section_title":"Health & Food Tips","intro":"Keep energy stable and hydration steady. Aim for balance, not perfection.","primary_sections":[{"title":"Suhoor ideas","items":["Oatmeal with nuts and dates","Eggs with whole-grain toast","Greek yogurt + berries","Chia pudding with milk","Water + herbal tea"]},{"title":"Iftar ideas","items":["Dates + water + light soup","Grilled protein + salad","Lentil soup + brown rice","Baked salmon + vegetables","Fresh fruit plate"]},{"title":"Wellness focus","items":["Avoid salty foods to reduce thirst","Prioritize complex carbs for longer energy","Short walks after Iftar","Limit heavy fried meals","Ease into caffeine to avoid dehydration"]}],"secondary_sections":[{"title":"Hydration plan","items":["Drink 8-10 glasses between iftar and suhoor","2 glasses at iftar","4 glasses between iftar and sleep","2-4 glasses at suhoor"]},{"title":"Sleep & movement","items":["Take a 20-30 minute power nap if needed","Sleep soon after Taraweeh","Dim screens 30 minutes before bed","Keep a consistent bedtime if possible","Light exercise 1-2 hours after iftar","Walking for 30 minutes","Light stretching","Avoid intense workouts during fasting hours"]}],"micro_tips":["Add fruit and vegetables to every meal.","Keep a water bottle nearby at night.","Reduce sugar spikes by breaking fast slowly."]},"duas_prayers":{"section_title":"Essential Duas & Supplications","intro":"Every dua below is verified from the Qur\'an or authentic hadith so you can recite with confidence.","tag_label":"Source","search_label":"Search Quran & Prophetic duas","daily_duas":[{"occasion":"Good in this life and the next","arabic":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً","transliteration":"Rabbana atina fid-dunya hasanah","translation":"Our Lord, give us good in this world","reference":"Qur\'an 2:201","link":"https://quran.com/2/201","source":"Qur\'an","tag":"Qur\'an"},{"occasion":"Steadfast hearts","arabic":"رَبَّنَا لَا تُزِغْ قُلُوبَنَا","transliteration":"Rabbana la tuzigh qulubana","translation":"Our Lord, do not let our hearts deviate","reference":"Qur\'an 3:8","link":"https://quran.com/3/8","source":"Qur\'an","tag":"Qur\'an"},{"occasion":"Guide us to the straight path","arabic":"اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","transliteration":"Ihdinas-siratal-mustaqim","translation":"Guide us to the straight path","reference":"Qur\'an 1:6","link":"https://quran.com/1/6","source":"Qur\'an","tag":"Qur\'an"},{"occasion":"Mercy from Allah","arabic":"رَبَّنَا هَبْ لَنَا مِنْ لَدُنْكَ رَحْمَةً","transliteration":"Rabbana hab lana min ladunka rahmah","translation":"Our Lord, grant us mercy from Yourself","reference":"Qur\'an 18:10","link":"https://quran.com/18/10","source":"Qur\'an","tag":"Qur\'an"},{"occasion":"Steadfast in prayer","arabic":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ","transliteration":"Rabbi ij\'alni muqima as-salah","translation":"My Lord, make me an establisher of prayer","reference":"Qur\'an 14:40","link":"https://quran.com/14/40","source":"Qur\'an","tag":"Qur\'an"},{"occasion":"Patience & resilience","arabic":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا","transliteration":"Rabbana afrigh \'alayna sabran","translation":"Our Lord, pour upon us patience","reference":"Qur\'an 2:250","link":"https://quran.com/2/250","source":"Qur\'an","tag":"Qur\'an"}],"view_more_label":"Explore the verified dua library","modal_title":"Dua Library","modal_sections":[{"title":"Worship & Prayer","items":[{"name":"Ease in prayer","arabic":"رَبِّ اشْرَحْ لِي صَدْرِي","transliteration":"Rabbi ishrah li sadri","translation":"My Lord, expand for me my chest","reference":"Qur\'an 20:25","resource":"https://quran.com/20/25","source":"Qur\'an"},{"name":"Increase knowledge","arabic":"رَبِّ زِدْنِي عِلْمًا","transliteration":"Rabbi zidni \'ilma","translation":"My Lord, increase me in knowledge","reference":"Qur\'an 20:114","resource":"https://quran.com/20/114","source":"Qur\'an"},{"name":"Guidance","arabic":"اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ","transliteration":"Ihdinas-siratal-mustaqim","translation":"Guide us to the straight path","reference":"Qur\'an 1:6","resource":"https://quran.com/1/6","source":"Qur\'an"},{"name":"Devotion","arabic":"رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ","transliteration":"Rabbana waj\'alna muslimayn","translation":"Our Lord, make us Muslims in submission to You","reference":"Qur\'an 2:128","resource":"https://quran.com/2/128","source":"Qur\'an"},{"name":"Prayer in family","arabic":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ","transliteration":"Rabbi ij\'alni muqima as-salah","translation":"My Lord, make me an establisher of prayer","reference":"Qur\'an 14:40","resource":"https://quran.com/14/40","source":"Qur\'an"}]},{"title":"Forgiveness & Mercy","items":[{"name":"Do not burden us","arabic":"رَبَّنَا لَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ","transliteration":"Rabbana la tuhammilna ma la taqata lana bih","translation":"Our Lord, do not burden us beyond what we can bear","reference":"Qur\'an 2:286","resource":"https://quran.com/2/286","source":"Qur\'an"},{"name":"Mercy","arabic":"رَبِّ اغْفِرْ وَارْحَمْ","transliteration":"Rabbi ighfir warham","translation":"My Lord, forgive and have mercy","reference":"Qur\'an 23:118","resource":"https://quran.com/23/118","source":"Qur\'an"},{"name":"Repentance","arabic":"رَبَّنَا ظَلَمْنَا أَنْفُسَنَا","transliteration":"Rabbana zalamna anfusana","translation":"Our Lord, we have wronged ourselves","reference":"Qur\'an 7:23","resource":"https://quran.com/7/23","source":"Qur\'an"},{"name":"Forgive our sins","arabic":"رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا","transliteration":"Rabbana ighfir lana dhunubana","translation":"Our Lord, forgive us our sins","reference":"Qur\'an 3:147","resource":"https://quran.com/3/147","source":"Qur\'an"},{"name":"Light for us","arabic":"رَبَّنَا أَتْمِمْ لَنَا نُورَنَا","transliteration":"Rabbana atmim lana nurana","translation":"Our Lord, perfect for us our light","reference":"Qur\'an 66:8","resource":"https://quran.com/66/8","source":"Qur\'an"},{"name":"Turn away punishment","arabic":"رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ","transliteration":"Rabbana isrif \'anna \'adhaba jahannam","translation":"Our Lord, turn away from us the punishment of Hell","reference":"Qur\'an 25:65","resource":"https://quran.com/25/65","source":"Qur\'an"}]},{"title":"Family & Community","items":[{"name":"Righteous family","arabic":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا","transliteration":"Rabbana hab lana min azwajina","translation":"Our Lord, grant us from among our spouses","reference":"Qur\'an 25:74","resource":"https://quran.com/25/74","source":"Qur\'an"},{"name":"Parents and believers","arabic":"رَبِّ اغْفِرْ لِي وَلِوَالِدَيَّ","transliteration":"Rabbi ighfir li wa li walidayya","translation":"My Lord, forgive me and my parents","reference":"Qur\'an 14:41","resource":"https://quran.com/14/41","source":"Qur\'an"},{"name":"Peaceful home","arabic":"رَبِّ أَنزِلْنِي مُنزَلًا مُّبَارَكًا","transliteration":"Rabbi anzilni munzalan mubaraka","translation":"My Lord, let me land at a blessed landing place","reference":"Qur\'an 23:29","resource":"https://quran.com/23/29","source":"Qur\'an"},{"name":"Clean hearts","arabic":"رَبَّنَا لَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا","transliteration":"Rabbana la taj\'al fi qulubina ghillan","translation":"Our Lord, do not place in our hearts any rancor","reference":"Qur\'an 59:10","resource":"https://quran.com/59/10","source":"Qur\'an"},{"name":"Do not leave me alone","arabic":"رَبِّ لَا تَذَرْنِي فَرْدًا","transliteration":"Rabbi la tadharni fardan","translation":"My Lord, do not leave me alone while You are the best of inheritors","reference":"Qur\'an 4:129","resource":"https://quran.com/4/129","source":"Qur\'an"}]},{"title":"Provision & Resilience","items":[{"name":"Good provision","arabic":"رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ","transliteration":"Rabbi inni lima anzalta ilayya min khayrin faqir","translation":"My Lord, I am in need of whatever good You send down to me","reference":"Qur\'an 28:24","resource":"https://quran.com/28/24","source":"Qur\'an"},{"name":"Blessed wealth","arabic":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً","transliteration":"Rabbana atina fid-dunya hasanah","translation":"Our Lord, give us good in this world","reference":"Qur\'an 2:201","resource":"https://quran.com/2/201","source":"Qur\'an"},{"name":"Accepted deeds","arabic":"رَبَّنَا تَقَبَّلْ مِنَّا","transliteration":"Rabbana taqabbal minna","translation":"Our Lord, accept from us","reference":"Qur\'an 2:127","resource":"https://quran.com/2/127","source":"Qur\'an"},{"name":"Steadfast faith","arabic":"رَبَّنَا عَلَيْكَ تَوَكَّلْنَا","transliteration":"Rabbana \'alayka tawakkalna","translation":"Our Lord, upon You we rely","reference":"Qur\'an 10:85","resource":"https://quran.com/10/85","source":"Qur\'an"},{"name":"Patience in trials","arabic":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا","transliteration":"Rabbana afrigh \'alayna sabran","translation":"Our Lord, pour upon us patience","reference":"Qur\'an 2:250","resource":"https://quran.com/2/250","source":"Qur\'an"},{"name":"Turn away punishment","arabic":"رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ","transliteration":"Rabbana isrif \'anna \'adhaba jahannam","translation":"Our Lord, turn away from us the punishment of Hell","reference":"Qur\'an 25:65","resource":"https://quran.com/25/65","source":"Qur\'an"}]},{"title":"Prophetic Supplications","items":[{"name":"Guidance & piety","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى","transliteration":"Allahumma inni as\'alukal-huda wat-tuqa wal-\'afafa wal-ghina","translation":"O Allah, I ask You for guidance, piety, chastity, and contentment","reference":"Sunan Ibn Majah 3832","resource":"https://sunnah.com/ibnmajah:3832","source":"Hadith"},{"name":"Beneficial knowledge, provision & deeds","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا","transliteration":"Allahumma inni as\'aluka ilman nafi\'an, wa rizqan tayyiban, wa amalan mutaqabbalan","translation":"O Allah, I ask You for beneficial knowledge, good provision, and accepted deeds","reference":"Sunan Ibn Majah 925","resource":"https://sunnah.com/ibnmajah:925","source":"Hadith"},{"name":"Forgiveness & well-being","arabic":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ","transliteration":"Allahumma inni as\'alukal-\'afwa wal-\'afiyah fid-dunya wal-akhirah","translation":"O Allah, I ask You for forgiveness and well-being in this world and the Hereafter","reference":"Sunan Ibn Majah 3871","resource":"https://sunnah.com/ibnmajah:3871","source":"Hadith"}]}]},"shorts":{"section_title":"Ramadan Short Clips","subtitle":"Quick, inspiring clips grouped by theme. Tap any card to watch.","highlights_title":"Quick highlights","highlights":[{"title":"Ramadan is coming","description":"A quick reminder to prepare your heart and schedule.","duration":"Under 1 min","tag":"Preparation","link":"https://www.youtube.com/shorts/HRHR66dGphk","thumbnail":"https://i.ytimg.com/vi/HRHR66dGphk/hqdefault.jpg"},{"title":"Which one are you this Ramadan?","description":"A short reflection on personal goals.","duration":"Under 1 min","tag":"Reflection","link":"https://www.youtube.com/shorts/ubK3uJzcS6k","thumbnail":"https://i.ytimg.com/vi/ubK3uJzcS6k/hqdefault.jpg"},{"title":"Ramadan Mubarak dua","description":"Short dua to share blessings in the month.","duration":"Under 1 min","tag":"Dua","link":"https://www.youtube.com/shorts/V3VN1lkfrjM","thumbnail":"https://i.ytimg.com/vi/V3VN1lkfrjM/hqdefault.jpg"},{"title":"Shortest fasting times","description":"A quick look at shorter fasting windows by region.","duration":"Under 1 min","tag":"Fasting","link":"https://www.youtube.com/shorts/xX74aNqVf28","thumbnail":"https://i.ytimg.com/vi/xX74aNqVf28/hqdefault.jpg"}],"groups":[{"title":"Quran & Taraweeh","items":[{"title":"Ramadan reminder","description":"Keep the Quran close and hearts soft.","duration":"Under 1 min","tag":"Quran","link":"https://www.youtube.com/shorts/nOG_AO74gFE","thumbnail":"https://i.ytimg.com/vi/nOG_AO74gFE/hqdefault.jpg"},{"title":"Quran in Ramadan","description":"Quick motivation to recite more.","duration":"Under 1 min","tag":"Quran","link":"https://www.youtube.com/watch?v=_P32u0x2v_w","thumbnail":"https://i.ytimg.com/vi/_P32u0x2v_w/hqdefault.jpg"},{"title":"Fast Taraweeh","description":"A short reminder about nightly prayers.","duration":"Under 1 min","tag":"Taraweeh","link":"https://www.youtube.com/shorts/sTyXJo_O9zI","thumbnail":"https://i.ytimg.com/vi/sTyXJo_O9zI/hqdefault.jpg"}]},{"title":"Duas & Laylat al-Qadr","items":[{"title":"Ramadan dua","description":"A brief dua to recite in the month.","duration":"Under 1 min","tag":"Dua","link":"https://www.youtube.com/shorts/yBHKEwH89Co","thumbnail":"https://i.ytimg.com/vi/yBHKEwH89Co/hqdefault.jpg"},{"title":"Authentic dua at iftar","description":"Iftar dua reminder.","duration":"Under 1 min","tag":"Iftar","link":"https://www.youtube.com/shorts/O1z666oaa0U","thumbnail":"https://i.ytimg.com/vi/O1z666oaa0U/hqdefault.jpg"},{"title":"Laylat al-Qadr dua","description":"What to say on the Night of Power.","duration":"Under 1 min","tag":"Laylat al-Qadr","link":"https://www.youtube.com/shorts/lmnZZVZKuIY","thumbnail":"https://i.ytimg.com/vi/lmnZZVZKuIY/hqdefault.jpg"}]},{"title":"Suhoor & Charity","items":[{"title":"Eating suhoor in Ramadan","description":"A lighthearted look at suhoor routines.","duration":"Under 1 min","tag":"Suhoor","link":"https://www.youtube.com/shorts/2kyjR_uMnRw","thumbnail":"https://i.ytimg.com/vi/2kyjR_uMnRw/hqdefault.jpg"},{"title":"DIY Sadaqah box","description":"A creative charity idea for families.","duration":"Under 1 min","tag":"Charity","link":"https://www.youtube.com/shorts/Ycfzl4NjkmI","thumbnail":"https://i.ytimg.com/vi/Ycfzl4NjkmI/hqdefault.jpg"}]}]},"platform_resources":{"section_title":"Apps & Learning Resources","subtitle":"Choose the platform that suits your learning style.","intro":["Listed resources were checked against their official domains and app stores on February 4, 2026, so the URLs remain reachable.","We focus on app publishers and learning platforms backed by trusted teams, scholar-led research centers, or high-usage communities so you can prepare for Ramadan with confidence."],"cards":[{"title":"Verified Mobile Apps","description":"","items":[{"name":"Muslim Pro","label":"Muslim Pro","link":"https://www.muslimpro.com/","note":"Prayer times, Quran, and Ramadan reminders in one place with large global usage.","logo":"https://www.muslimpro.com/favicon.ico"},{"name":"Quran.com Mobile","label":"Quran.com Mobile","link":"https://quran.com/en/apps","note":"Ad-free Quran Foundation app with translations, recitations, tafsir access, and daily goals.","logo":"https://quran.com/favicon.ico"},{"name":"IslamicFinder Athan","label":"IslamicFinder Athan","link":"https://www.islamicfinder.org/prayer-times/","note":"Global prayer times with mosque directory, qibla support, and Hijri calendar features.","logo":"https://www.islamicfinder.org/favicon.ico"},{"name":"Quran Companion","label":"Quran Companion","link":"https://apps.apple.com/us/app/quran-companion-memorize-quran/id1111843462","note":"Memorization-focused experience with streaks, motivation tools, and guided review routines.","logo":"https://qurancompanion.com/favicon.ico"}]},{"title":"Interactive Learning Platforms","description":"","items":[{"name":"Bayyinah TV","label":"Bayyinah TV","link":"https://bayyinah.tv/","note":"Long-form Quran and Arabic video learning with family pathways and structured episodes.","logo":"https://bayyinah.tv/favicon.ico"},{"name":"Yaqeen Institute Ramadan","label":"Yaqeen Institute Ramadan","link":"https://yaqeeninstitute.org/ramadan","note":"Research-backed Ramadan reflections, videos, and journals with downloadable resources.","logo":"https://yaqeeninstitute.org/favicon.ico"},{"name":"SeekersGuidance","label":"SeekersGuidance","link":"https://seekersguidance.org/","note":"Non-profit seminary with structured courses, Q&A resources, and guided learning tracks.","logo":"https://seekersguidance.org/favicon.ico"},{"name":"Quran Academy","label":"Quran Academy","link":"https://quranacademy.io/","note":"Quranic Arabic learning pathways with challenges, memorization support, and coach-led sessions.","logo":"https://quranacademy.io/favicon.ico"}]},{"title":"Audio & Qur’an Study Tools","description":"","items":[{"name":"QuranicAudio","label":"QuranicAudio","link":"https://quranicaudio.com/","note":"Large reciter library with downloadable MP3 and flexible streaming playback.","logo":"https://quranicaudio.com/favicon.ico"},{"name":"Mushafi Quran","label":"Mushafi Quran","link":"https://mushafiquran.com/","note":"Word-by-word meaning, offline packs, and tajwid-friendly recitation tools.","logo":"https://mushafiquran.com/favicon.ico"},{"name":"HifzPath","label":"HifzPath","link":"https://hifzpath.pages.dev/","note":"Memorization tracking with streak tools, quick quizzes, and revision support.","logo":"https://hifzpath.pages.dev/favicon.ico"},{"name":"Quran IQ","label":"Quran IQ","link":"https://quraniq.com/","note":"Arabic vocabulary and grammar drills for understanding Quranic language with guided lessons.","logo":"https://quraniq.com/favicon.ico"}]}]},"faq":{"section_title":"Frequently Asked Questions","subtitle":"Answers reflect the Umm al-Qura calendar (official Saudi calendar) for Ramadan 1447 AH. Local moon sighting and regional methodologies may produce different dates; always verify with your local religious authority or masjid.","items":[{"question":"When does Ramadan 2026 start?","answer":"According to the Umm al-Qura calendar the official administrative calendar of Saudi Arabia, the first day of fasting is on the February 19, 2026 , with the first Taraweeh prayer on the night of February 18, 2026 (29 Sha‘ban 1447 AH). These dates are pre-calculated and used for planning purposes. Actual observance in any country remains subject to local moon sighting, which may shift the start by ±1 day. Please confirm with your local masjid."},{"question":"What time does the daily fast begin and end?","answer":"Fasting is from true dawn (Fajr) until sunset (Maghrib). Follow your local prayer timetable for your exact city times; timetables based on the Umm al-Qura calendar are available for Saudi Arabia and some other regions."},{"question":"Who is exempt from fasting?","answer":"Children before puberty, the ill, travelers, pregnant or nursing women, and those menstruating are exempt. Missed fasts are made up later when possible; ask a local scholar about fidya or kaffarah in your situation."},{"question":"What breaks the fast?","answer":"Eating or drinking, sexual relations, intentional vomiting, and menstrual or postpartum bleeding break the fast. If you eat or drink out of forgetfulness, the fast remains valid according to most Sunni opinions."},{"question":"How can I make the most of the last 10 nights?","answer":"Prioritize night prayer, Quran, dua, and charity, and focus on the odd nights (21, 23, 25, 27, 29) for Laylat al-Qadr. Under the Umm al-Qura calendar, the 27th night falls on March 16–17, 2026 (evening of March 16 entering March 17), but the exact night is not fixed. Many people adjust sleep schedules or take time off to focus on worship."}]},"tools_calculators":{"section_title":"Ramadan Starter Kit","subtitle":"Direct access to Islamic Connect tools.","intro":["Use this hub to reach zakat calculators, dua collections, surah resources, podcasts, the seerah timeline, and prayer calendars without guessing where to go next.","Each card opens the tool in a new tab so you can drop into the experience you need while you keep reading the Ramadan guide."],"tools":[{"title":"Zakat Calculator","description":"Estimate your zakat obligations with step-by-step guidance ahead of Ramadan.","detail":"Answer a few questions about savings, investments, and liabilities to see what you owe before Eid.","link":"/zakat","icon":"fa-calculator"},{"title":"Surat Explorer","description":"Browse suwar summaries, audio, and study notes for focused reading.","detail":"Compare tafsir notes, choose reciters, and plan quran sessions so every surah has context.","link":"/surat","icon":"fa-book-open"},{"title":"Prayer Times Calendar","description":"Track global prayer schedules with a comprehensive calendar view.","detail":"Sync sunrise, sunset, and city-specific reminders so you never miss a dawah moment.","link":"/prayer","icon":"fa-globe"}]}}')},89876:function(a,e,t){t.r(e),t.d(e,{default:function(){return i}});var i=t(69097).A}}]);